style:
/* 鎏金 —— 「个人简历」标头与金色实底标题条 */

.tw-liujin.layout-band.resume-paper .paper-flow::before {
  content: "个 人 简 历";
  display: block;
  margin-bottom: 5mm;
  padding-bottom: 2.4mm;
  border-bottom: 1.2mm solid var(--paper-accent);
  color: #2a2318;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.35);
  font-weight: 700;
  letter-spacing: 0.18em;
  print-color-adjust: exact;
}

.tw-liujin.layout-band.resume-paper .paper-header::before {
  content: "PERSONAL RESUME";
  display: block;
  margin-bottom: 1.8mm;
  color: #a8894a;
  font-size: calc(var(--paper-base-size) * 0.76);
  font-weight: 700;
  letter-spacing: 0.34em;
  flex: 0 0 100%;
  width: 100%;
  text-align: right;
}

.tw-liujin.layout-band.resume-paper .paper-header {
  margin-bottom: 6.5mm;
  padding-bottom: 4mm;
  border-bottom: 0.25mm solid #e8dfcd;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 8mm;
}

.tw-liujin.layout-band.resume-paper .paper-header__main {
  flex: 1 1 0;
  min-width: 0;
}

.tw-liujin.layout-band.resume-paper .paper-photo {
  order: 3;
  width: 25mm;
  height: 33mm;
  padding: 1.2mm;
  border: 0.35mm solid var(--paper-accent);
  border-radius: 0;
  background: #fff;
  box-shadow: none;
}

.tw-liujin.layout-band.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #faf6ee;
  color: #a8894a;
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-liujin.layout-band.resume-paper .paper-name {
  color: #2a2318;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.05);
  letter-spacing: 0.08em;
}

.tw-liujin.layout-band.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #7c6f58;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-liujin.layout-band.resume-paper .paper-role {
  margin-top: 1.4mm;
  color: #4a4235;
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 400;
}

.tw-liujin.layout-band.resume-paper .paper-contacts {
  display: flex;
  flex-wrap: wrap;
  gap: 1.4mm 6mm;
  margin-top: 3mm;
  padding-top: 0;
  border-top: none;
  color: #4a4235;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-liujin.layout-band.resume-paper .paper-contact {
  display: inline-flex;
  gap: 1.4mm;
}

.tw-liujin.layout-band.resume-paper .paper-contact + .paper-contact::before {
  content: "";
  left: -3mm;
  width: 0.2mm;
  height: 3.2mm;
  background: #e3d8c2;
  print-color-adjust: exact;
}

.tw-liujin.layout-band.resume-paper .paper-contact__label {
  color: #8d8168;
}

/* 标题：金色整条 + 白字 + 左侧小图标 */
.tw-liujin.layout-band.resume-paper .paper-style-block .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  margin-bottom: 3.2mm;
  padding: 1.2mm 3.2mm;
  background: var(--paper-accent);
  border-radius: 0;
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1.04);
  letter-spacing: 0.12em;
  print-color-adjust: exact;
}

.tw-liujin.layout-band.resume-paper .paper-style-block .paper-section__icon {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  width: 4mm;
  height: 4mm;
  color: #fff;
}

.tw-liujin.layout-band.resume-paper .paper-style-block .paper-section__icon svg {
  width: 100%;
  height: 100%;
}

.tw-liujin.layout-band.resume-paper .paper-section__body {
  color: #3b352b;
}

.tw-liujin.layout-band.resume-paper .paper-item-title {
  color: #2a2318;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-liujin.layout-band.resume-paper .paper-item-period {
  color: #8a7d64;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-liujin.layout-band.resume-paper .paper-item-sub {
  color: #4f473a;
}

.tw-liujin.layout-band.resume-paper .paper-rich ul,
.tw-liujin.layout-band.resume-paper .paper-rich ol {
  padding-left: 1.1em;
}

.tw-liujin.layout-band.resume-paper .paper-rich li::marker {
  color: var(--paper-accent);
}

.tw-liujin.layout-band.resume-paper .paper-skills {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2mm 7mm;
}

.tw-liujin.layout-band.resume-paper .paper-skill {
  display: block;
  padding-bottom: 0;
  border-bottom: none;
}

.tw-liujin.layout-band.resume-paper .paper-skill__name {
  display: block;
  font-size: calc(var(--paper-base-size) * 0.9);
  font-weight: 400;
}

.tw-liujin.layout-band.resume-paper .paper-skill__dots {
  display: flex;
  gap: 0;
  margin-top: 1.2mm;
}

.tw-liujin.layout-band.resume-paper .paper-skill__dots i {
  width: 100%;
  height: 1.8mm;
  border-radius: 0;
  background: #eee7d8;
}

.tw-liujin.layout-band.resume-paper .paper-skill__dots i.filled {
  background: var(--paper-accent);
}

.tw-liujin.layout-band.resume-paper .paper-skill__level {
  display: block;
  margin-top: 1mm;
  color: #8a7d64;
  font-size: calc(var(--paper-base-size) * 0.8);
}

.tw-liujin.layout-band.resume-paper .paper-note__tag {
  color: #a8894a;
  font-weight: 600;
}

.tw-liujin.layout-band.resume-paper .paper-footer {
  border-top: 0.2mm solid #eee7d8;
  color: #a89e8c;
}
